contract InvMutTest {
    C c;
    address payable deployer;
    constructor(C _c) {
        c = _c;
        // record the deployer of this test contract so we can distinguish callers
        deployer = payable(address(this));
    }

    // Run with a single boolean parameter indicating whether the test should attempt the call
    // from the owner (this contract) or emulate a non-owner caller by using a try/catch on a low-level call.
    function run(bool callAsOwner) public payable {
        require(true);

        // Ensure this test contract holds at least some Ether to observe transfers if selfdestruct happens
        // (the test harness will provide msg.value to this run call if desired)

        // Snapshot balances before the call
        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;

        bool reverted;
        // If callAsOwner is true, call sudicideAnyone directly (msg.sender == InvMutTest -> owner)
        if (callAsOwner) {
            try c.sudicideAnyone() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // Emulate a non-owner by performing a low-level call from this contract to c via an internal call
            // Since msg.sender will still be this contract, we cannot change msg.sender. To simulate a non-owner,
            // we call a minimal proxy pattern: perform a call to address(c) using call with encoded selector
            // but mark it as from a different address is impossible here, so instead we check the behavior
            // by invoking the function via call and observing revert (it should revert because only owner allowed).
            (bool ok, ) = address(c).call(abi.encodeWithSignature("sudicideAnyone()"));
            reverted = !ok;
        }

        uint256 afterC = address(c).balance;
        uint256 afterThis = address(this).balance;

        // General rule to assert:
        // If the call reverted then balances must be unchanged; otherwise (call succeeded) the c's balance must have been transferred to msg.sender (this contract)
        assert(
            (reverted && beforeC == afterC && beforeThis == afterThis) ||
            (!reverted && afterC == 0 && afterThis == beforeThis + beforeC)
        );
    }

    // accept Ether so selfdestruct can send funds here
    receive() external payable {}
}

