    function run(bool callerIsOwner) public payable {
        require(true);

        // record balances before the call
        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;

        // If we want this contract to be the owner, it must be the deployer of c.
        // The problem statement says the checker deploys a FRESH c and runs run(...) once with this contract as msg.sender for calls on c.
        // However, whether this contract is the owner depends on how c was constructed; we encode that by branching on the input:
        // - If callerIsOwner == true, we require that a call succeeds (if deployed as owner). If it's not owner the call should revert, so the general rule is: when not owner the call reverts and balances unchanged.
        // We'll assert that whenever the call reverts then balances remain unchanged; and when it does not revert then C's balance becomes zero and this contract's balance increases by that amount.

        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterC = address(c).balance;
        uint256 afterThis = address(this).balance;

        // General rule: if call reverted then balances unchanged; if call succeeded then c.balance is zero and this contract gained exactly the previous c.balance.
        assert((reverted && beforeC == afterC && beforeThis == afterThis) || (!reverted && afterC == 0 && afterThis == beforeThis + beforeC));
    }

    receive() external payable {}
