contract InvMutTest {
    C c;
    address payable owner;
    constructor(C _c) {
        c = _c;
        // The deployer of C is the test deployer of the whole system (per problem statement),
        // but within checks the InvMutTest is the msg.sender when calling c; we record owner as payable(address(this))
        owner = payable(address(this));
    }

    // single public test function taking an input: whether to call as owner (true) or simulate non-owner (false)
    function run(bool callAsOwner) public payable {
        require(true);
        // Ensure we have some Ether to fund c if desired
        uint fund = msg.value;
        if (fund > 0) {
            // send Ether to c to observe selfdestruct forwarding
            // must ensure this contract has the Ether (msg.value provided)
            (bool sent, ) = address(c).call{value: fund}(""");
            // ignore send result; some C implementations may not accept plain transfers but balance may still change via payable fallback
            sent; 
        }

        bool reverted;
        // We need to call c.sudicideAnyone. Only the owner (which is address(this) per sGuardPlus constructor when InvMutTest deployed C) may succeed.
        // To simulate a non-owner call, we deploy an inner call via a helper contract; but helpers aren't allowed. Instead we use call with data from this contract but with a different msg.sender is impossible.
        // Alternative: use low-level call to c from this contract (which is the owner), and check behavior: it should succeed and forward balance.
        // To test non-owner revert, we perform the call via address(c).call by encoding function selector but using a contract-call context: that's still from this contract.
        // Since we cannot change msg.sender, we instead branch: when callAsOwner==true we call directly; when false we assert that attempting to call via address(c).call still has same sender and therefore will not revert — to create a meaningful universal property, we assert that the balance of c becomes zero if and only if the call did not revert.

        // Record c balance before
        uint beforeBal = address(c).balance;

        // Attempt the call and capture revert
        try c.sudicideAnyone{value: 0}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBal = address(c).balance;
        // If the call succeeded (not reverted), then selfdestruct should have sent c's funds to the caller (this contract), so c's balance becomes 0 and this contract's balance increases by beforeBal.
        // If the call reverted, balances should be unchanged on c.
        if (!reverted) {
            assert(afterBal == 0 && address(this).balance >= beforeBal);
        }
        // If reverted, ensure c's balance stayed the same
        else {
            assert(afterBal == beforeBal);
        }
    }

    // accept Ether forwarded by selfdestruct
    receive() external payable {}
}

