contract InvMutTest {
    C c;
    address deployer;

    constructor(C _c) {
        c = _c;
        // record deployer as the address that deployed C (in this testing setup, the checker deploys C separately)
        // We cannot read owner (it's private), so we capture deployer as address(this) if this contract deployed C,
        // but to be general we allow the caller of run to supply a flag whether the test contract is owner.
    }

    // Single public test function per constraints. It takes a boolean indicating whether this test contract is
    // the owner of C (true) or not (false), and an amount of wei to send when attempting the call.
    function run(bool callerIsOwner, uint amount) public payable {
        require(address(this).balance >= amount, "insufficient balance to send");

        // Read balance before call
        uint beforeBalance = address(c).balance;

        // Attempt to call sudicideAnyone and catch whether it reverted.
        bool reverted;
        // c.sudicideAnyone is restricted by __onlyOwner, so it should succeed iff msg.sender == owner.
        // Our test contract will be msg.sender for this call. The callerIsOwner parameter is a hint about
        // whether this InvMutTest contract is the owner of c; the property asserts the relation between that
        // hint and whether the call reverts and whether the contract's balance changes.
        try c.sudicideAnyone{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBalance = address(c).balance;

        // General rule:
        // - If callerIsOwner == true then the call must NOT revert, and afterBalance must be <= beforeBalance
        //   (selfdestruct would send funds away so balance may decrease by at most amount or more if contract had funds).
        // - If callerIsOwner == false then the call MUST revert, and afterBalance must equal beforeBalance (no state change).
        assert(
            (callerIsOwner && !reverted && afterBalance <= beforeBalance)
            || (!callerIsOwner && reverted && afterBalance == beforeBalance)
        );
    }

    receive() external payable {}
}

