        bool thisIsOwner = false;
        // We cannot read private owner variable; infer ownership by checking if a successful call happened.
        // If call succeeded, then this contract must be owner. If call reverted, we conservatively allow revert.
        if (!reverted) {
            thisIsOwner = true;
        }

        // Final assertion: either successful destructive transfer happened, or revert left balances as before;
        // and if the call succeeded then it implies this contract was owner (inferred) — so require the transfer effect.
        assert((!reverted && afterC == 0 && afterThis == beforeThis + beforeC) || (reverted && afterC == beforeC && afterThis == beforeThis));
